from __future__ import annotations
import cmath, math
from typing import Callable
CFunc = Callable[[float], complex]
def winding(field: CFunc, derivative: CFunc, n: int = 4096) -> complex:
    step = 2 * math.pi / n
    return step * sum(derivative(j*step)/field(j*step) for j in range(n)) / (2j*math.pi)
def mode(m: int) -> tuple[CFunc, CFunc]:
    f = lambda t: (1 + .25*math.cos(t))*cmath.exp(1j*m*t)
    df = lambda t: (-.25*math.sin(t)+1j*m*(1+.25*math.cos(t)))*cmath.exp(1j*m*t)
    return f, df
for m in (-4, 0, 3):
    print(m, winding(*mode(m)))

from __future__ import annotations
import cmath, math
from typing import Callable
F = Callable[[float], complex]
def helix(q: int) -> tuple[F, F]:
    return (lambda t: cmath.exp(1j*q*t), lambda t: 1j*q*cmath.exp(1j*q*t))
def power(pair: tuple[F,F], k: int) -> tuple[F,F]:
    f, df = pair
    return lambda t: f(t)**k, lambda t: 0j if k == 0 else k*f(t)**(k-1)*df(t)
def product(a: tuple[F,F], b: tuple[F,F]) -> tuple[F,F]:
    f,df=a; g,dg=b
    return lambda t:f(t)*g(t), lambda t:df(t)*g(t)+f(t)*dg(t)
def winding(pair: tuple[F,F], n: int=4096) -> complex:
    f,df=pair; h=2*math.pi/n
    return h*sum(df(j*h)/f(j*h) for j in range(n))/(2j*math.pi)
gamma, delta = helix(2), helix(-3)
for k, ell in [(4,-1),(3,2),(-2,-2)]:
    observed=winding(product(power(gamma,k),power(delta,ell)))
    print(k, ell, observed, "expected", 2*k-3*ell)

from __future__ import annotations
import cmath, math
from typing import Callable
def phase_winding(field: Callable[[float],complex], n: int=4096) -> float:
    z=[field(2*math.pi*j/n) for j in range(n)]
    return sum(cmath.phase(b/a) for a,b in zip(z,z[1:]+z[:1]))/(2*math.pi)
for q in range(-3,4):
    field=lambda t,q=q:(1+.4*math.cos(t))*cmath.exp(1j*q*t)
    print(q, phase_winding(field))

